<?php require 'admin_guard.php';require 'admin_db.php';if($_SERVER['REQUEST_METHOD']==='POST'){$s=mysqli_prepare($conn,'INSERT INTO admin_messages(fromAdmin,toAdmin,message) VALUES(?,?,?)');mysqli_stmt_bind_param($s,'sss',$adminID,$_POST['toAdmin'],$_POST['message']);mysqli_stmt_execute($s);} $admins=mysqli_query($conn,"SELECT AdminID,name FROM admin_info WHERE AdminID<> '".mysqli_real_escape_string($conn,$adminID)."'");$msgs=mysqli_query($conn,"SELECT m.*,a.name FROM admin_messages m LEFT JOIN admin_info a ON a.AdminID=m.fromAdmin WHERE m.toAdmin='".mysqli_real_escape_string($conn,$adminID)."' OR m.fromAdmin='".mysqli_real_escape_string($conn,$adminID)."' ORDER BY m.created_at DESC");?><!doctype html><html><head><title>Admin Messages</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>Response Other Admins</h1><a class="btn" href="admin_dashboard.php">Dashboard</a></div><div class="panel"><form method="post"><select name="toAdmin" required><option value="">Select admin</option><?php while($a=mysqli_fetch_assoc($admins)):?><option><?=$a['AdminID']?></option><?php endwhile;?></select><textarea name="message" required placeholder="Message"></textarea><button>Send</button></form></div><div class="panel"><table><tr><th>From</th><th>To</th><th>Message</th><th>Date</th></tr><?php while($m=mysqli_fetch_assoc($msgs)):?><tr><td><?=$m['fromAdmin']?></td><td><?=$m['toAdmin']?></td><td><?=htmlspecialchars($m['message'])?></td><td><?=$m['created_at']?></td></tr><?php endwhile;?></table></div></div></body></html>
